import os

def batch_rename(folder, prefix):
    for i, name in enumerate(os.listdir(folder), 1):
        src = os.path.join(folder, name)
        if os.path.isfile(src):
            ext = os.path.splitext(name)[1]
            dst = os.path.join(folder, f"{prefix}_{i:03d}{ext}")
            os.rename(src, dst)
            print(f"{name} -> {os.path.basename(dst)}")

batch_rename('./photos', 'vacation')

import requests, time

def fetch_with_retry(url, retries=3, delay=1):
    for i in range(retries):
        try:
            resp = requests.get(url, timeout=5)
            resp.raise_for_status()
            return resp.json()
        except requests.RequestException as e:
            print(f"第 {i+1} 次失败：{e}")
            if i < retries - 1:
                time.sleep(delay * (i + 1))
    raise RuntimeError("请求多次失败")

data = fetch_with_retry('https://api.example.com/items')
